Here's a simple C++ code for a calculator that performs basic arithmetic operations like addition, subtraction, multiplication, and division.

```cpp
#include <iostream>
using namespace std;

// Function to add two numbers
double add(double num1, double num2) {
    return num1 + num2;
}

// Function to subtract two numbers
double subtract(double num1, double num2) {
    return num1 - num2;
}

// Function to multiply two numbers
double multiply(double num1, double num2) {
    return num1 * num2;
}

// Function to divide two numbers
double divide(double num1, double num2) {
    if (num2 == 0) {
        cout << "Error: Division by zero is not allowed." << endl;
        return 0;
    }
    return num1 / num2;
}

int main() {
    int choice;
    double num1, num2, result;

    cout << "Simple Calculator" << endl;
    cout << "1. Addition" << endl;
    cout << "2. Subtraction" << endl;
    cout << "3. Multiplication" << endl;
    cout << "4. Division" << endl;
    cout << "5. Exit" << endl;

    while (true) {
        cout << "Enter your choice (1-5): ";
        cin >> choice;

        if (choice == 5) {
            break;
        }

        cout << "Enter the first number: ";
        cin >> num1;

        cout << "Enter the second number: ";
        cin >> num2;

        switch (choice) {
            case 1:
                result = add(num1, num2);
                cout << "Result: " << result << endl;
                break;
            case 2:
                result = subtract(num1, num2);
                cout << "Result: " << result << endl;
                break;
            case 3:
                result = multiply(num1, num2);
                cout << "Result: " << result << endl;
                break;
            case 4:
                result = divide(num1, num2);
                break;
            default:
                cout << "Invalid choice. Please try again." << endl;
                break;
        }
    }

    return 0;
}
```

This code uses a simple menu-driven approach to allow the user to choose the operation they want to perform. It then prompts the user to enter the two numbers and displays the result. The code also includes error checking to prevent division by zero.
